// Prism grammar for Trux (.tx). Loaded on demand by Prism's autoloader for
// ```trux code blocks. The token lists mirror internal/token/token.go, the
// builtins in internal/types, and the packages in internal/stdlib; keep them
// in sync when the language grows.
Prism.languages.trux = {
  comment: { pattern: /\/\/.*/, greedy: true },
  string: {
    pattern: /"(?:\\.|[^"\\\r\n])*"/,
    greedy: true,
    inside: { escape: { pattern: /\\./, alias: "entity" } }
  },
  "package-name": {
    pattern: /\b(?:io|csv|errors|image|time|http|gpu|json|jwt|sqlite)(?=\.)/,
    alias: "namespace"
  },
  "class-name": [
    /\b[A-Za-z_]\w*(?=\s+struct\b)/,
    /\b[A-Z]\w*\b(?!\s*\()/,
    /\b(?:int|float|string|bool|error|list|map|Buffer)\b/
  ],
  keyword: /\b(?:package|import|pub|type|struct|kernel|func|return|let|mut|if|else|for|break|continue|in)\b/,
  boolean: /\b(?:true|false)\b/,
  constant: /\bnil\b/,
  builtin: /\b(?:print|assert|len|append|clone|make|new|delete|keys|values)\b(?=\s*\()/,
  function: /\b[A-Za-z_]\w*(?=\s*\()/,
  number: /\b\d+(?:\.\d+)?\b/,
  operator: /==|!=|<=|>=|&&|\|\||[=!<>+\-*\/%&]/,
  punctuation: /[(){}\[\],:;.]/
};
Prism.languages.tx = Prism.languages.trux;
